const D = { density:.5, scale:1, hue:200, energy:.6, speed:1, x:.5, y:.5, spread:1, style:'prismatic', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI*2;
const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const MAXN = 150;

// ---- rebuild deterministic glint field on seed change ----
if (S.seedUsed !== P.seed || !S.sites) {
  S.seedUsed = P.seed;
  S.sites = [];
  for (let i = 0; i < MAXN; i++) {
    S.sites.push({
      bx: fr(i*3+1),
      by: fr(i*3+2),
      rate: 0.5 + fr(i*3+3)*3.4,
      ph: fr(i+11)*TAU,
      hj: (fr(i+29)-0.5)*70,
      sz: 0.55 + fr(i+53)*0.9,
      arms: (fr(i+71) < 0.4) ? 4 : 6,
      dr: 0.35 + fr(i+97)*0.55,          // real-time drift rate (rad/s)
      da: 0.04 + fr(i+131)*0.07,         // drift amp (canvas frac) — bigger travel
      orb: 0.6 + fr(i+149)*0.9,          // per-site orbit-speed multiplier
      sh: 3 + fr(i+167)*5
    });
  }
}

// ---- style ramps ----
const heat = b => {
  if (b < .3) return [hw(P.hue-40), 90, 30 + b*120];
  if (b < .6) return [hw(28), 95, 55 + (b-.3)*130];
  if (b < .85) return [hw(52), 90, 92];
  return [hw(52), 22, 100];
};
const spectrum = [0, 45, 130, 195, 265, 315];

const nActive = Math.round(Math.max(0, Math.min(1, P.density)) * MAXN);
const focusX = P.x, focusY = P.y;
const grow = 0.5 + P.spread*1.4;
const beatPop = K.pulse * P.energy;
const sizeU = u * 0.05 * P.scale;
// GLOBAL real-time field rotation about the focus — never rephases, drives motion floor
const rot = K.t * 0.17 * P.speed;
const cr = Math.cos(rot), sr = Math.sin(rot);

push();
blendMode(ADD);

// ---- slow ambient shimmer wash: faint large patches drifting in real time ----
// (raises moving-pixel coverage so the motion floor holds even when glints are sparse)
{
  const nP = 6;
  const washV = P.style==='silver' ? 4 : (P.style==='ink' ? 3.5 : 5);
  for (let i = 0; i < nP; i++) {
    const sp = 0.05 + fr(i*5+201)*0.05;
    const dx = Math.sin(K.t*sp*P.speed + i*1.7)*0.5 + 0.5;
    const dy = Math.cos(K.t*sp*0.8*P.speed + i*2.3)*0.5 + 0.5;
    const cxp = (focusX + (dx-0.5)*grow*1.1) * width;
    const cyp = (focusY + (dy-0.5)*grow*1.1) * height;
    const rad = u * (0.26 + fr(i+211)*0.12) * P.scale;
    let hh;
    if (P.style==='thermal') hh = hw(P.hue+8);
    else if (P.style==='prismatic') hh = hw(P.hue + Math.sin(K.t*0.2 + i)*40);
    else hh = hw(P.hue);
    const ss = (P.style==='silver'||P.style==='ink') ? 10 : 40;
    const swell = 0.7 + 0.3*Math.sin(K.t*0.5 + i*1.1);
    fill(hh, ss, 100, washV*swell*(0.7 + P.energy*0.5));
    ellipse(cxp, cyp, rad, rad*0.85);
  }
}

for (let i = 0; i < nActive; i++) {
  const st = S.sites[i];
  // slow real-time wander of each site's base position
  const dxw = Math.sin(K.t*st.dr*P.speed + st.ph)*st.da;
  const dyw = Math.cos(K.t*st.dr*0.8*P.speed + st.ph*1.3)*st.da;
  // rotate the whole (offset) field around the focus so every glint travels an arc
  let relx = (st.bx-0.5)*grow + dxw;
  let rely = (st.by-0.5)*grow + dyw;
  const ang0 = rot*st.orb;
  const c2 = Math.cos(ang0), s2 = Math.sin(ang0);
  const rrx = relx*c2 - rely*s2;
  const rry = relx*s2 + rely*c2;
  const px = (focusX + rrx) * width;
  const py = (focusY + rry) * height;
  if (px < -sizeU || px > width+sizeU || py < -sizeU || py > height+sizeU) continue;

  let tw = Math.pow(Math.max(0, Math.sin(K.t*st.rate*P.speed + st.ph)), st.sh);
  tw = tw*(0.4 + P.energy*0.6) + A.treble*0.7*fr(i+7) + beatPop*fr(i+3)*0.6 + 0.14;
  tw = Math.min(1.6, tw);
  if (tw < 0.04) continue;

  const sz = sizeU * st.sz * (0.4 + tw*0.75);
  const baseHue = hw(P.hue + st.hj);

  if (P.style === 'halftone') {
    const inks = [[190,80,95],[320,85,95],[52,90,100],[0,0,15]];
    noStroke();
    for (let k = 0; k < 4; k++) {
      const off = k*0.18;
      const ang = st.ph + k*1.1 + rot*0.5;
      const ox = Math.cos(ang)*sz*0.22, oy = Math.sin(ang)*sz*0.22;
      const c = inks[k];
      fill(c[0], c[1], c[2], 22 + tw*55);
      for (let d = 0; d < 6; d++) {
        const a2 = d/6*TAU + off;
        ellipse(px+ox+Math.cos(a2)*sz*0.32, py+oy+Math.sin(a2)*sz*0.32, sz*0.16, sz*0.16);
      }
    }
    continue;
  }

  const arms = st.arms;
  noStroke();
  for (let a = 0; a < arms; a++) {
    const ang = a/arms*TAU + rot*0.9 + st.ph*0.2;
    const len = sz * (a % 2 === 0 ? 1 : 0.55) * (0.85 + tw*0.6);
    const wdt = sz * 0.09 * (0.6 + tw*0.5);
    let h2, s2b, v2;
    if (P.style === 'prismatic') { h2 = hw(baseHue + spectrum[a % 6]); s2b = 88; v2 = 100; }
    else if (P.style === 'silver') { h2 = hw(P.hue); s2b = 8; v2 = 100; }
    else if (P.style === 'thermal') { const c = heat(Math.min(1,tw)); h2 = c[0]; s2b = c[1]; v2 = c[2]; }
    else { h2 = hw(P.hue-10); s2b = 12; v2 = 92; }
    const tipx = px + Math.cos(ang)*len, tipy = py + Math.sin(ang)*len;
    const pxn = Math.cos(ang+Math.PI/2)*wdt, pyn = Math.sin(ang+Math.PI/2)*wdt;
    fill(h2, s2b, v2, 32 + tw*55);
    triangle(px+pxn, py+pyn, px-pxn, py-pyn, tipx, tipy);
  }
  if (P.style === 'thermal') { const c = heat(Math.min(1,tw*1.1)); fill(c[0], c[1]*0.4, 100, 42+tw*55); }
  else if (P.style === 'silver' || P.style === 'ink') fill(hw(P.hue), 6, 100, 47+tw*50);
  else fill(hw(baseHue+20), 25, 100, 47+tw*55);
  ellipse(px, py, sz*0.44*(0.6+tw*0.5), sz*0.44*(0.6+tw*0.5));
}

// ---- shooting glints crossing the frame (continuous, two overlapping streaks) ----
if (P.density > 0.05) {
  for (let lane = 0; lane < 2; lane++) {
    const period = 4.2 + lane*1.3;
    const idx = Math.floor((K.t + lane*2.1) / period);
    const fp = ((K.t + lane*2.1) % period) / period;
    if (fp < 0.55) {
      const sy = fr(idx*13+2+lane*97)*height;
      const dir = fr(idx*13+3+lane*31) < 0.5 ? 1 : -1;
      const prog = fp/0.55;
      const sx = (dir > 0 ? -0.1 + prog*2.2 : 1.1 - prog*2.2) * width;
      const tw = Math.sin(prog*Math.PI);
      const trail = u*0.18*P.scale;
      const hh = hw(P.style==='prismatic' ? P.hue + fp*300 : ((P.style==='silver'||P.style==='ink')?P.hue:P.hue+30));
      const ss = (P.style==='silver'||P.style==='ink') ? 8 : 70;
      for (let t = 0; t < 7; t++) {
        const q = t/7;
        fill(hh, ss, 100, (20 + tw*45)*(1-q));
        noStroke();
        ellipse(sx - dir*trail*q, sy + q*trail*0.15, u*0.014*P.scale*(1-q*0.6), u*0.014*P.scale*(1-q*0.6));
      }
    }
  }
}

blendMode(BLEND);
pop();
if (drawingContext) drawingContext.shadowBlur = 0;
